def is_palindrome(word):
    left = 0
    right = len(word) - 1
    while left < right:
        if word[left] != word[right]:
            return False
        left += 1
        right -= 1
    return True

print(is_palindrome(clean_text("No lemon, no melon")))

def pair_with_sum(numbers, target):
    pairs = []
    left = 0
    right = len(numbers) - 1
    while left < right:
        current_sum = numbers[left] + numbers[right]
        if current_sum == target:
            pairs.append((numbers[left], numbers[right]))
            left += 1
            right -= 1
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return pairs

print(pair_with_sum([1, 2, 3, 4, 5, 6], 7))

